CustomField.formula:
if(AND(TEXT(Status) != 'Closed', TEXT(Status) != 'Future'),
8 * (
( 5 * FLOOR( ( DATEVALUE( NOW() ) - DATE( 1900, 1, 8) ) / 7) +
MIN(5,
MOD( DATEVALUE( NOW() ) - DATE( 1900, 1, 8), 7) +
MIN( 1, 24 / 8 * ( MOD( NOW() - DATETIMEVALUE( '1900-01-08 13:00:00' ), 1 ) ) )
)
)
-
( 5 * FLOOR( ( DATEVALUE(Start_Date_Time__c) - DATE( 1900, 1, 8) ) / 7) +
MIN( 5,
MOD( DATEVALUE(Start_Date_Time__c) - DATE( 1996, 1, 1), 7 ) +
MIN( 1, 24 / 8 * ( MOD( Start_Date_Time__c - DATETIMEVALUE( '1900-01-08 13:00:00' ), 1) ) )
)
)
), On_Completion_Hour__c
)
